 function header(pane){const selected=pane==='school'?'schools':pane==='scores'||pane==='calendar'?'admissions':pane==='planner'||pane==='career'?'study':pane;return '<header class="hhu-topbar uw-topbar"><a class="hhu-brand" href="#/university"><span aria-hidden="true">U</span><strong>HH UNIVERSITY<small>Đại học & Cao đẳng Việt Nam</small></strong></a><nav aria-label="Điều hướng Đại học">'+nav.map(([id,label,suffix])=>href('/university'+suffix,esc(label),selected===id?'aria-current="page"':'')).join('')+'</nav><small class="uw-nav-hint">↔ Vuốt thanh mục để khám phá thêm</small></header>';}
 function roles(user){let s;try{s=T.state(JSON.parse(root.localStorage.getItem(T.preferenceKey(user))||'null'));}catch{s=T.defaults();}return '<div class="uw-role-grid"><article class="uw-role"><span class="uw-role-symbol" aria-hidden="true">↗</span><small>CHUẨN BỊ BƯỚC TIẾP THEO</small><h2>Tôi đang chọn trường, chọn ngành</h2><p>So sánh chương trình, sắp xếp nguyện vọng và giữ lịch tuyển sinh trong cùng một nơi.</p><div class="hhu-actions">'+href('/university/majors','Khám phá ngành','class="hhu-primary"')+href('/university/wishes','Nguyện vọng của tôi · '+s.wishes.length)+'</div></article><article class="uw-role"><span class="uw-role-symbol" aria-hidden="true">▦</span><small>HỌC TẬP CÓ KẾ HOẠCH</small><h2>Tôi đang là sinh viên</h2><p>Tiếp tục học, theo dõi tín chỉ, tính GPA và ôn lại điều mình còn vướng.</p><div class="hhu-actions">'+href('/university/study','Tiếp tục Bàn học','class="hhu-primary"')+href('/university/planner','Kế hoạch & GPA')+'</div></article></div>'+(s.events.filter(e=>!e.done&&e.date>=today()).length?'<aside class="uw-banner">Bạn có '+s.events.filter(e=>!e.done&&e.date>=today()).length+' mốc sắp tới. '+href('/university/calendar','Mở lịch cá nhân')+'</aside>':'');}
