 function schoolExtras(school){const p=R.profiles[school.institution.id];if(!p)return '<aside class="uw-banner">Thông tin liên hệ, cơ sở học và học phí mở rộng chưa được xác minh cho hồ sơ này. '+href('/university/quality?school='+school.institution.id,'Gửi nguồn bổ sung')+'</aside>';return '<section class="hhu-panel uw-profile"><div><small>THÔNG TIN ĐỐI CHIẾU</small><h2>Kết nối đúng cơ sở đào tạo</h2><p>'+esc([p.email,p.phone].filter(Boolean).join(' · '))+'</p><div class="hhu-actions">'+external(p.website,'Website trường')+external(p.admissionsWebsite,'Cổng tuyển sinh')+href('/university/finance?school='+school.institution.id,'Học phí & học bổng')+'</div>'+sourceLink(p.sourceId)+'</div><div>'+p.campuses.map(c=>'<article><strong>'+esc(c.name)+'</strong><p>'+esc(c.address)+'</p></article>').join('')+'<p class="hhu-muted">'+esc(p.dormitory)+'</p></div></section>';}
 function historyChart(groups){return groups.filter(C.canTrend).filter(g=>Object.values(g.values).flat().every(r=>r.score>=0&&r.score<=g.scale)).map(g=>{const years=C.YEARS,values=years.map(y=>g.values[y]?.[0]?.score??null),scale=g.scale,points=values.map((v,i)=>v===null?null:{x:45+i*70,y:180-v/scale*145,value:v,year:years[i]}),segments=[];let current=[];for(const p of points){if(p)current.push(p);else{if(current.length)segments.push(current);current=[];}}if(current.length)segments.push(current);return '<figure class="uw-chart"><figcaption>'+esc(g.method)+' · thang '+num(scale)+' · '+esc(g.combination||'Tổ hợp chưa nêu')+'</figcaption><svg viewBox="0 0 515 220" role="img" aria-label="Điểm cùng phương thức và thang điểm; khoảng thiếu dữ liệu không được nối"><path d="M35 20V185H490" fill="none" stroke="currentColor" opacity=".3"/>'+segments.map(s=>s.length>1?'<polyline fill="none" stroke="currentColor" stroke-width="3" points="'+s.map(p=>p.x+','+p.y).join(' ')+'"/>':'').join('')+points.filter(Boolean).map(p=>'<circle cx="'+p.x+'" cy="'+p.y+'" r="4" fill="currentColor"/><text x="'+p.x+'" y="'+(p.y-12)+'" text-anchor="middle">'+num(p.value)+'</text>').join('')+years.map((y,i)=>'<text x="'+(45+i*70)+'" y="208" text-anchor="middle">'+y+'</text>').join('')+'</svg><p class="hhu-muted">Tổ hợp, phương thức, thang điểm và đợt được giữ riêng. Biểu đồ không dự đoán điểm năm sau.</p></figure>';}).join('');}
 const cache=new Map();async function load(entry,signal){if(cache.has(entry.url))return cache.get(entry.url);if(!/^data\/hh-(?:university|school)\/[a-z0-9/-]+\.json\?v=[a-f0-9]{12}$/.test(entry.url))throw Error('Đường dẫn học liệu chưa hợp lệ.');const r=await root.fetch(new URL(entry.url,document.baseURI),{signal,credentials:'same-origin'});if(!r.ok)throw Error('Chưa tải được dữ liệu (HTTP '+r.status+').');const bytes=new Uint8Array(await r.arrayBuffer());if(bytes.length>8*1048576)throw Error('Gói dữ liệu vượt giới hạn.');const hash=Array.from(new Uint8Array(await root.crypto.subtle.digest('SHA-256',bytes)),v=>v.toString(16).padStart(2,'0')).join('');if(bytes.length!==entry.bytes||hash!==entry.sha256)throw Error('Dữ liệu không khớp bản đã kiểm tra; chưa sử dụng.');const value=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));if(value.schemaVersion!==1||value.version!==entry.version)throw Error('Phiên bản dữ liệu chưa được hỗ trợ.');cache.set(entry.url,value);if(cache.size>12)cache.delete(cache.keys().next().value);return value;}
