  function transact(update){if(protectedState){feedback('Hãy xuất bản gốc và khôi phục hồ sơ trước khi lưu thay đổi.');return false;}let next;try{if(memoryOnly)next=T.state(store);else{let current;try{current=root.localStorage.getItem(key);}catch{memoryOnly=true;current=undefined;}try{next=T.state(current===undefined?store:current?JSON.parse(current):store);}catch(e){protectedState=true;feedback(e.message);return false;}}update(next);store=T.state(next);}catch(e){feedback(e.message);return false;}if(!memoryOnly){try{root.localStorage.setItem(key,JSON.stringify(store));storageError='';}catch{memoryOnly=true;storageError='Chưa lưu được trên thiết bị.';}}if(memoryOnly)feedback('Thay đổi được giữ trong phiên này.');return true;}
