  function secondary(){return '<nav class="uw-secondary" aria-label="Công cụ cá nhân">'+[['saved','Trường đã lưu'],['calendar','Lịch & hồ sơ'],['planner','Kế hoạch & GPA'],['career','Kỹ năng & CV'],['quality','Nguồn & chất lượng']].map(([id,label])=>href('/university/'+id,esc(label),pane===id?'aria-current="page"':'')).join('')+'<span>'+store.compare.length+'/4 so sánh · '+store.wishes.length+' nguyện vọng</span></nav>';}
