  function change(event){const el=event.target;try{
   if(el.closest('[data-uw-form=ai]')&&['mode','aiSchool','aiProgram','courseId','year'].includes(el.name)&&aiBusy){aiVersion++;aiRequest?.abort();aiBusy=false;updateAI();host.querySelector('[data-uw-ai-result]').innerHTML=aiResultView();feedback('Đã hủy yêu cầu trước khi đổi ngữ cảnh.');}
   if(el.name==='selectionSchool'||el.name==='aiSchool'){selectedSchool=el.value;selectedProgram='';const target=host.querySelector('[name='+(el.name==='aiSchool'?'aiProgram':'selectionProgram')+']');if(target)target.innerHTML='<option value="">Chọn chương trình</option>'+programmes.filter(p=>p.schoolId===selectedSchool).map(p=>'<option value="'+p.programId+'">'+esc(p.code+' · '+p.title)+'</option>').join('');}
   else if(el.name==='selectionProgram'||el.name==='aiProgram')selectedProgram=el.value;
   else if(el.name==='ruleId'){ruleId=el.value;draw();}
   else if(el.name==='localPdf')void openPDF(el.files?.[0]).catch(e=>feedback(e.message));
   else if(el.name==='quizAnswer'){transact(s=>{if(s.quiz&&!s.quiz.submitted)s.quiz.answers[s.quiz.index]=Number(el.value);});draw();}
   else if(el.dataset.uwEventDone){transact(s=>{const e=s.events.find(v=>v.id===el.dataset.uwEventDone);if(e)e.done=el.checked;});}
   else if(el.dataset.uwTaskDone){transact(s=>{const t=s.tasks.find(v=>v.id===el.dataset.uwTaskDone);if(t)t.done=el.checked;});}
   else if(el.dataset.uwSkill){transact(s=>{s.career.skills=s.career.skills.filter(v=>v!==el.dataset.uwSkill);if(el.checked)s.career.skills.push(el.dataset.uwSkill);});}
   else if(el.dataset.uwProject){transact(s=>{const p=s.projects.find(v=>v.id===el.dataset.uwProject);if(p)p.done=el.checked;});}
  }catch(e){feedback(e.message);}}
  function input(){/* Forms persist explicitly; server status updates never replace a draft. */}
  function storage(event){if(event.key!==key)return;if(memoryOnly){feedback('Cửa sổ khác vừa đổi hồ sơ trên thiết bị. Bản đang làm trong phiên được giữ để xuất riêng.');return;}try{store=T.state(event.newValue?JSON.parse(event.newValue):null);protectedState=false;if(!host.contains(document.activeElement)||document.activeElement.tagName==='BUTTON')draw();else feedback('Hồ sơ đã đổi ở cửa sổ khác. Biểu mẫu đang nhập được giữ nguyên.');}catch{protectedState=true;feedback('Dữ liệu mới cần khôi phục; bản gốc chưa bị ghi đè.');}}
