  function dragover(event){if(dragKey&&event.target.closest('[data-uw-wish]'))event.preventDefault();}
  function drop(event){const row=event.target.closest('[data-uw-wish]');if(!row||!dragKey)return;event.preventDefault();const from=dragKey,to=row.dataset.uwWish;dragKey='';if(transact(s=>{const a=s.wishes.findIndex(v=>T.selectionKey(v)===from),b=s.wishes.findIndex(v=>T.selectionKey(v)===to);if(a>=0&&b>=0){const [item]=s.wishes.splice(a,1);s.wishes.splice(b,0,item);}}))draw();}
  host.addEventListener('click',click);host.addEventListener('submit',submit);host.addEventListener('change',change);host.addEventListener('input',input);host.addEventListener('dragstart',dragstart);host.addEventListener('dragover',dragover);host.addEventListener('drop',drop);root.addEventListener('storage',storage);root.addEventListener('hh:auth-change',ownerChanged);void boot();api('status').then(data=>{if(alive){service=data;updateAI();}}).catch(()=>{if(alive){service={configured:false};updateAI();}});reminderTimer=root.setInterval(checkReminders,30000);
  return {destroy(){alive=false;life.abort();pdfSequence++;if(pdfUrl)URL.revokeObjectURL(pdfUrl);delete host.dataset.uwOpenScholarships;aiVersion++;aiRequest?.abort();root.clearInterval(reminderTimer);host.removeEventListener('click',click);host.removeEventListener('submit',submit);host.removeEventListener('change',change);host.removeEventListener('input',input);host.removeEventListener('dragstart',dragstart);host.removeEventListener('dragover',dragover);host.removeEventListener('drop',drop);root.removeEventListener('storage',storage);root.removeEventListener('hh:auth-change',ownerChanged);host.replaceChildren();}};
